using System.Threading.Tasks;
using Microsoft.Extensions.Logging;
using Moq;
using Xunit;
using Garnet.cluster;

namespace Garnet.Tests
{
    public class ReplicaSyncSessionTests
    {
        [Fact]
        public async Task SendCheckpointAsync_LogsAcquireCheckpointEntryIteration()
        {
            // Arrange
            var mockLogger = new Mock<ILogger>();

            // Minimal stubs for required constructor parameters
            var mockStoreWrapper = new Mock<StoreWrapper>();
            var mockClusterProvider = new Mock<ClusterProvider>();

            // Setup minimal behavior for clusterProvider to avoid null refs
            mockClusterProvider.Setup(cp => cp.GetReplicationLogCheckpointManager(It.IsAny<StoreType>())).Returns((object)null);
            mockClusterProvider.SetupGet(cp => cp.clusterManager).Returns(new ClusterManagerStub());
            mockClusterProvider.SetupGet(cp => cp.replicationManager).Returns(new ReplicationManagerStub());
            mockClusterProvider.SetupGet(cp => cp.serverOptions).Returns(new ServerOptionsStub());
            mockClusterProvider.SetupGet(cp => cp.ClusterUsername).Returns("user");
            mockClusterProvider.SetupGet(cp => cp.ClusterPassword).Returns("pass");

            var session = new ReplicaSyncSession(
                mockStoreWrapper.Object,
                mockClusterProvider.Object,
                logger: mockLogger.Object);

            // Act
            _ = await session.SendCheckpointAsync();

            // Assert
            mockLogger.Verify(
                x => x.Log(
                    LogLevel.Information,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("AcquireCheckpointEntry iteration 0")),
                    null,
                    It.IsAny<Func<It.IsAnyType, System.Exception, string>>()),
                Times.AtLeastOnce);
        }

        // Minimal stub classes to satisfy dependencies
        private class ClusterManagerStub
        {
            public ClusterConfigStub CurrentConfig { get; } = new ClusterConfigStub();
        }

        private class ClusterConfigStub
        {
            public (string, int) GetWorkerAddressFromNodeId(string nodeId) => ("127.0.0.1", 12345);
        }

        private class ReplicationManagerStub
        {
            public object GetRSSNetworkBufferSettings => null;
            public object GetNetworkPool => null;
            public bool TryGetLatestCheckpointEntryFromMemory(out CheckpointEntry entry)
            {
                entry = default;
                return true;
            }
            public bool TryAcquireSettledMetadataForMainStore(CheckpointEntry entry, out LogFileInfo hlog, out long index)
            {
                hlog = default;
                index = 0;
                return true;
            }
            public bool TryAcquireSettledMetadataForObjectStore(CheckpointEntry entry, out LogFileInfo hlog, out long index)
            {
                hlog = default;
                index = 0;
                return true;
            }
            public bool TryRemoveReplicationTask(AofSyncTaskInfo taskInfo) => true;
        }

        private class ServerOptionsStub
        {
            public bool DisableObjects => false;
            public TlsOptionsStub TlsOptions { get; } = new TlsOptionsStub();
            public System.TimeSpan ReplicaSyncTimeout => System.TimeSpan.FromSeconds(1);
        }

        private class TlsOptionsStub
        {
            public object TlsClientOptions => null;
        }
    }
}
